<!doctype html><html><head><meta charset="utf-8"><title><?= e($estimate['estimate_number']) ?></title><style>body{font-family:DejaVu Sans,Arial,sans-serif;color:#172033;font-size:12px;margin:35px}*{box-sizing:border-box}.head{overflow:hidden;border-bottom:3px solid #0794b5;padding-bottom:18px}.brand{float:left;font-size:22px;font-weight:bold;color:#101936}.brand span{color:#0794b5}.doc{float:right;text-align:right}.meta{display:table;width:100%;margin:25px 0}.meta>div{display:table-cell;width:50%;vertical-align:top}.right{text-align:right}h1{font-size:24px;margin:0;color:#101936;text-transform:uppercase}.muted{color:#667085}table{width:100%;border-collapse:collapse;margin-top:22px}th{background:#101936;color:white;text-align:left;padding:10px}td{padding:10px;border-bottom:1px solid #e4e7ec}.totals{width:42%;margin:20px 0 0 auto}.totals div{overflow:hidden;padding:6px}.totals span:last-child{float:right}.grand{border-top:2px solid #101936;font-size:16px;font-weight:bold}.foot{margin-top:40px;padding-top:15px;border-top:1px solid #e4e7ec;text-align:center;color:#667085}</style></head><body><div class="head"><div class="brand">Rankers <span>Mind</span><div class="muted" style="font-size:12px;font-weight:normal">Kolkata, West Bengal, India</div></div><div class="doc"><h1><?= e($estimate['estimate_type']) ?></h1><strong><?= e($estimate['estimate_number']) ?></strong></div></div><div class="meta"><div><span class="muted">PREPARED FOR</span><h3><?= e($estimate['company_name']) ?></h3><p><?= nl2br(e($estimate['billing_address']?:$estimate['city'].', '.$estimate['state'])) ?><br><?= e($estimate['email']) ?></p></div><div class="right"><p><span class="muted">Date:</span> <?= e(date('d M Y',strtotime($estimate['estimate_date']))) ?><br><span class="muted">Valid until:</span> <?= $estimate['valid_until']?e(date('d M Y',strtotime($estimate['valid_until']))):'—' ?><br><span class="muted">Project:</span> <?= e($estimate['project_name']?:'General') ?><br><span class="muted">Status:</span> <strong><?= e($estimate['status']) ?></strong></p></div></div><table><thead><tr><th>Description</th><th class="right">Qty</th><th class="right">Rate</th><th class="right">Tax</th><th class="right">Amount</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?= e($item['description']) ?></td><td class="right"><?= e($item['quantity']) ?></td><td class="right"><?= money($item['rate']) ?></td><td class="right"><?= e($item['tax_percent']) ?>%</td><td class="right"><?= money($item['amount']) ?></td></tr><?php endforeach;?></tbody></table><div class="totals"><div><span>Subtotal</span><span><?= money($estimate['subtotal']) ?></span></div><div><span>Tax</span><span><?= money($estimate['tax_total']) ?></span></div><div><span>Discount</span><span><?= money($estimate['discount_total']) ?></span></div><div class="grand"><span>Grand total</span><span><?= money($estimate['grand_total']) ?></span></div></div><h4>Notes & terms</h4><p><?= nl2br(e($estimate['notes'])) ?></p><p class="muted"><?= nl2br(e($estimate['terms'])) ?></p><div class="foot">This is a computer-generated estimate from Rankers Mind CRM.</div><script>if(!new URLSearchParams(location.search).has('format'))window.print()</script></body></html>
